class Main {
  public static void main(String[] args) {
    // -128 to 127
    byte roll = 7;
    // 2 bytes
    short sem = 4;
    // 4 bytes
    int marks = 452;
    // suffix L
    long mob = 9876543210L;
    // suffix f
    float per = 78.5f;
    // 8 bytes
    double cgpa = 8.25;
    // single quotes
    char sec = 'A';
    // true or false only
    boolean ok = true;

    System.out.println("roll = " + roll);
    System.out.println("sem = " + sem);
    System.out.println("marks = " + marks);
    System.out.println("mobile = " + mob);
    System.out.println("per = " + per);
    System.out.println("cgpa = " + cgpa);
    System.out.println("section = " + sec);
    System.out.println("passed = " + ok);
  }
}

class Main {
  public static void main(String[] args) {
    int a = 17, b = 5;
    int add = a + b, sub = a - b;
    int mul = a * b;
    // int division: 3
    int div = a / b;
    // remainder: 2
    int rem = a % b;
    System.out.println("add = " + add);
    System.out.println("sub = " + sub);
    System.out.println("mul = " + mul);
    System.out.println("div = " + div);
    System.out.println("rem = " + rem);

    // type casting
    double exact = (double) a / b;
    System.out.println("exact = " + exact);

    // double -> int
    int r = (int) 9.7;
    System.out.println("cast = " + r);

    char ch = 'A';
    // char -> int (auto)
    int code = ch;
    char nx = (char)(ch + 1);
    System.out.println("code = " + code);
    System.out.println("next = " + nx);
  }
}

class Main {
  public static void main(String[] args) {
    // born here
    int x = 10;
    System.out.println("x = " + x);
    {
      // born in inner block
      int y = 20;
      System.out.println("y = " + y);
      // outer var visible
      int z = x + y;
      System.out.println("x + y = " + z);
    }
    // y = 30;  // ERROR: y died at the }
    // up to here x lives, y and z are gone
    System.out.println("x again = " + x);
  }
}

class Main {
  public static void main(String[] args) {
    int a = 10, b = 3;
    System.out.println("a/b = " + (a / b));
    System.out.println("a%b = " + (a % b));

    // relational
    System.out.println("a>b = " + (a > b));
    // logical
    boolean ok = (a > 5) && (b < 5);
    System.out.println("both = " + ok);

    // bitwise AND
    System.out.println("a&b = " + (a & b));
    // bitwise OR
    System.out.println("a|b = " + (a | b));
    // XOR
    System.out.println("a^b = " + (a ^ b));
    int sh = a << 1;
    // shift
    System.out.println("a<<1 = " + sh);

    int max = (a > b) ? a : b;    // ternary
    System.out.println("max = " + max);

    // use, then add 1
    int c = a++;
    // add 1, then use
    int d = ++a;
    System.out.println("c = " + c);
    System.out.println("d = " + d);
  }
}

class Main {
  public static void main(String[] args) {
    int marks = 72;

    // 1. simple if
    if (marks >= 35)
      System.out.println("Result: Pass");

    // 2. if-else
    if (marks >= 60) {
      System.out.println("Type: First");
    } else {
      System.out.println("Type: below 60");
    }

    // 3. if-else-if ladder
    if (marks >= 70)
      System.out.println("Grade: A");
    else if (marks >= 60)
      System.out.println("Grade: B");
    else if (marks >= 50)
      System.out.println("Grade: C");
    else if (marks >= 35)
      System.out.println("Grade: D");
    else
      System.out.println("Grade: Fail");
  }
}

class Main {
  public static void main(String[] args) {
    int a = 25, b = 40, c = 15;
    int g;
    // outer if
    if (a > b) {
      // inner if
      if (a > c)
        g = a;
      else
        g = c;
    } else {
      // nested in else
      if (b > c)
        g = b;
      else
        g = c;
    }
    System.out.println("greatest = " + g);
  }
}

class Main {
  public static void main(String[] args) {
    int day = 3;
    switch (day) {
      case 1:
        System.out.println("Monday");
        break;
      case 2:
        System.out.println("Tuesday");
        break;
      case 3:
        System.out.println("Wednesday");
        break;
      case 4:
        System.out.println("Thursday");
        break;
      case 5:
        System.out.println("Friday");
        break;
      default:
        System.out.println("Weekend");
    }

    // switch on a String (Java 7+)
    String op = "+";
    int x = 8, y = 4;
    int res = 0;
    switch (op) {
      case "+":
        res = x + y;
        break;
      case "*":
        res = x * y;
        break;
      default:
        res = -1;
    }
    System.out.println("result = " + res);
  }
}

class Main {
  public static void main(String[] args) {
    // 1. for: fixed count
    System.out.println("Table of 7:");
    for (int i = 1; i <= 5; i++) {
      int p = 7 * i;
      System.out.println(i + " x 7 = " + p);
    }

    // 2. while: check before entering
    int n = 160, count = 0;
    // count the digits
    while (n > 0) {
      n = n / 10;
      count++;
    }
    System.out.println("digits = " + count);

    // 3. do-while: body runs at least once
    int k = 5;
    do {
      System.out.println("k = " + k);
      k--;
    } while (k > 0);
  }
}

class Main {
  public static void main(String[] args) {
    int num = 4782;
    int n = num;
    int sum = 0;
    while (n != 0) {
      int d = n % 10;     // last digit
      sum = sum + d;
      n = n / 10;         // drop last digit
    }
    System.out.println("number = " + num);
    System.out.println("sum = " + sum);
  }
}

class Main {
  public static void main(String[] args) {
    // continue: skip to the next round
    System.out.print("odd numbers 1..9: ");
    for (int i = 1; i <= 9; i++) {
      if (i % 2 == 0)
        continue;          // skip evens
      System.out.print(i + " ");
    }
    System.out.println();

    // break: leave the loop immediately
    int[] stops = {3, 5, 12, 7, 9};
    for (int s : stops) {
      if (s > 10) {
        System.out.println("big = " + s);
        break;             // stop searching
      }
    }
  }
}

class Main {
  public static void main(String[] args) {
    // declare + initialize in one step
    int[] marks = {78, 85, 66, 90, 71};

    // traversal with index
    System.out.println("All marks:");
    for (int i = 0; i < marks.length; i++) {
      int m = marks[i];
      System.out.println(i + " : " + m);
    }

    // sum and average with for-each
    int sum = 0;
    for (int m : marks)
      sum += m;
    double avg = 1.0 * sum / marks.length;

    System.out.println("sum = " + sum);
    System.out.println("average = " + avg);
  }
}

class Main {
  public static void main(String[] args) {
    int[][] a = {{1, 2, 3},
                 {4, 5, 6}};
    int[][] b = {{7, 8, 9},
                 {1, 2, 3}};
    int rows = a.length;
    int cols = a[0].length;
    int[][] sum = new int[rows][cols];

    for (int i = 0; i < rows; i++) {
      for (int j = 0; j < cols; j++) {
        sum[i][j] = a[i][j] + b[i][j];
        System.out.print(sum[i][j] + " ");
      }
      System.out.println();      // next row
    }
  }
}

class Main {
  public static void main(String[] args) {
    int[] t = {42, 17, 55, 9, 31};
    int min = t[0];
    int max = t[0];
    for (int v : t) {
      if (v < min)
        // new minimum found
        min = v;
      if (v > max)
        // new maximum found
        max = v;
    }
    System.out.println("smallest = " + min);
    System.out.println("largest = " + max);
  }
}

class Main {
  public static void main(String[] args) {
    // pattern 1: right triangle
    for (int i = 1; i <= 4; i++) {
      for (int j = 1; j <= i; j++)
        System.out.print("* ");
      System.out.println();
    }

    // pattern 2: number triangle
    System.out.println("---");
    for (int i = 4; i >= 1; i--) {
      for (int j = i; j >= 1; j--)
        System.out.print(j + " ");
      System.out.println();
    }
  }
}

